                             ER_CLIENT(CR_SERVER_LOST_EXTENDED),
                             "waiting for initial communication packet",
                             socket_errno);
    return STATE_MACHINE_FAILED;
  }
  ctx->state_function = csm_read_greeting;
  return STATE_MACHINE_CONTINUE;
}


